@* Summary stats bar showing task counts *@

<div class="board-stats">
    <span class="stat">Total: <strong>@Total</strong></span>
    <span class="stat">To Do: <strong>@TodoCount</strong></span>
    <span class="stat">In Progress: <strong>@InProgressCount</strong></span>
    <span class="stat">Done: <strong>@DoneCount</strong></span>
    <span class="stat stat-overdue">Overdue: <strong>@OverdueCount</strong></span>
</div>

@code {
    [Parameter, EditorRequired]
    public List<TaskItem> Tasks { get; set; } = new();

    private int Total => Tasks.Count;
    private int TodoCount => Tasks.Count(t => t.Status == "To Do");
    private int InProgressCount => Tasks.Count(t => t.Status == "In Progress");
    private int DoneCount => Tasks.Count(t => t.Status == "Done");
    private int OverdueCount => Tasks.Count(t => t.DueDate < DateTime.Today);
}

@* Search bar for filtering tasks by title *@

<div class="board-search">
    <input type="text" placeholder="Search tasks by title..." value="@SearchText"
           @oninput="OnInput" />
</div>

@code {
    [Parameter]
    public string SearchText { get; set; } = string.Empty;

    [Parameter]
    public EventCallback<string> OnSearchChanged { get; set; }

    private async Task OnInput(ChangeEventArgs e)
    {
        await OnSearchChanged.InvokeAsync(e.Value?.ToString() ?? string.Empty);
    }
}

@* A single Kanban column with its tasks and add form *@

<div class="board-column">
    <div class="column-header">
        <h3>@ColumnName</h3>
        <span class="column-count">@Tasks.Count</span>
    </div>
    <div class="column-tasks">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      CanMoveLeft="CanMoveLeft"
                      CanMoveRight="CanMoveRight"
                      OnMoveLeft="OnMoveLeft"
                      OnMoveRight="OnMoveRight" />
        }
    </div>
    <AddTaskForm Status="@ColumnName" OnTaskCreated="OnTaskCreated" />
</div>

@code {
    [Parameter, EditorRequired]
    public string ColumnName { get; set; } = default!;

    [Parameter, EditorRequired]
    public List<TaskItem> Tasks { get; set; } = new();

    [Parameter]
    public bool CanMoveLeft { get; set; }

    [Parameter]
    public bool CanMoveRight { get; set; }

    [Parameter]
    public EventCallback<TaskItem> OnMoveLeft { get; set; }

    [Parameter]
    public EventCallback<TaskItem> OnMoveRight { get; set; }

    [Parameter]
    public EventCallback<(string Title, string Assignee, string Priority, DateTime DueDate)> OnTaskCreated { get; set; }
}

@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h1>Kanban Board</h1>

@if (isLoading)
{
    <p class="loading">Loading tasks...</p>
}
else if (errorMessage is not null)
{
    <p class="error">@errorMessage</p>
}
else
{
    <BoardStats Tasks="allTasks" />
    <BoardSearchBar SearchText="@searchText" OnSearchChanged="HandleSearchChanged" />

    <div class="board-columns">
        <BoardColumn ColumnName="To Do"
                     Tasks="GetTasksForColumn(\"To Do\")"
                     CanMoveLeft="false"
                     CanMoveRight="true"
                     OnMoveRight="MoveRight"
                     OnTaskCreated="args => HandleTaskCreated(\"To Do\", args)" />

        <BoardColumn ColumnName="In Progress"
                     Tasks="GetTasksForColumn(\"In Progress\")"
                     CanMoveLeft="true"
                     CanMoveRight="true"
                     OnMoveLeft="MoveLeft"
                     OnMoveRight="MoveRight"
                     OnTaskCreated="args => HandleTaskCreated(\"In Progress\", args)" />

        <BoardColumn ColumnName="Done"
                     Tasks="GetTasksForColumn(\"Done\")"
                     CanMoveLeft="true"
                     CanMoveRight="false"
                     OnMoveLeft="MoveLeft"
                     OnTaskCreated="args => HandleTaskCreated(\"Done\", args)" />
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private string searchText = string.Empty;
    private bool isLoading = true;
    private string? errorMessage;

    private static readonly string[] Columns = { "To Do", "In Progress", "Done" };

    protected override async Task OnInitializedAsync()
    {
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private List<TaskItem> GetTasksForColumn(string status)
    {
        var tasks = allTasks.Where(t => t.Status == status);
        if (!string.IsNullOrWhiteSpace(searchText))
        {
            tasks = tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));
        }
        return tasks.ToList();
    }

    private void HandleSearchChanged(string text)
    {
        searchText = text;
    }

    private async Task MoveLeft(TaskItem task)
    {
        var currentIndex = Array.IndexOf(Columns, task.Status);
        if (currentIndex > 0)
        {
            var newStatus = Columns[currentIndex - 1];
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            UpdateTaskStatus(task, newStatus);
        }
    }

    private async Task MoveRight(TaskItem task)
    {
        var currentIndex = Array.IndexOf(Columns, task.Status);
        if (currentIndex < Columns.Length - 1)
        {
            var newStatus = Columns[currentIndex + 1];
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            UpdateTaskStatus(task, newStatus);
        }
    }

    private void UpdateTaskStatus(TaskItem task, string newStatus)
    {
        var index = allTasks.FindIndex(t => t.Id == task.Id);
        if (index >= 0)
        {
            allTasks[index] = task with { Status = newStatus };
        }
    }

    private async Task HandleTaskCreated(string status, (string Title, string Assignee, string Priority, DateTime DueDate) args)
    {
        var newTask = await TaskService.CreateTaskAsync(args.Title, args.Assignee, args.Priority, args.DueDate);
        // CreateTaskAsync may not set the status to the column's status, so ensure it matches
        if (newTask.Status != status)
        {
            newTask = newTask with { Status = status };
        }
        allTasks.Add(newTask);
    }
}

