toolArgs.file_text:
.board-columns {
    display: flex;
    gap: 1.5rem;
    margin-top: 1rem;
}

.board-stats {
    display: flex;
    gap: 1.5rem;
    flex-wrap: wrap;
    padding: 0.75rem 1rem;
    background: #f0f4f8;
    border-radius: 0.5rem;
    margin-bottom: 1rem;
}

.stat {
    font-size: 0.9rem;
}

.stat-overdue strong {
    color: #dc3545;
}

.board-search {
    margin-bottom: 1rem;
}

.board-search input {
    width: 100%;
    max-width: 400px;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 0.375rem;
    font-size: 0.9rem;
}

::deep .board-column {
    flex: 1;
    min-width: 250px;
    background: #f8f9fa;
    border-radius: 0.5rem;
    padding: 1rem;
    display: flex;
    flex-direction: column;
}

::deep .column-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

::deep .column-header h3 {
    margin: 0;
    font-size: 1.1rem;
}

::deep .column-count {
    background: #6c757d;
    color: white;
    border-radius: 50%;
    width: 1.5rem;
    height: 1.5rem;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.8rem;
}

::deep .column-tasks {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    margin-bottom: 0.75rem;
}

::deep .task-card {
    background: white;
    border: 1px solid #dee2e6;
    border-radius: 0.375rem;
    padding: 0.75rem;
}

::deep .task-title {
    margin: 0 0 0.25rem;
    font-size: 0.95rem;
}

::deep .task-assignee {
    margin: 0 0 0.5rem;
    font-size: 0.8rem;
    color: #6c757d;
}

::deep .priority-badge {
    display: inline-block;
    padding: 0.15rem 0.5rem;
    border-radius: 0.25rem;
    font-size: 0.75rem;
    font-weight: 600;
    margin-right: 0.5rem;
}

::deep .priority-high {
    background: #f8d7da;
    color: #842029;
}

::deep .priority-medium {
    background: #fff3cd;
    color: #664d03;
}

::deep .priority-low {
    background: #d1e7dd;
    color: #0f5132;
}

::deep .task-due-date {
    font-size: 0.8rem;
    color: #6c757d;
}

::deep .task-actions {
    margin-top: 0.5rem;
    display: flex;
    gap: 0.5rem;
}

